import '@testing-library/jest-dom/jest-globals';
import { beforeEach, describe, expect, it, jest } from '@jest/globals';
import { render, screen } from '@testing-library/react';
import {
    DUE_STATISTICS_SUMMARY_ENTRY_BLUR_PX,
    DUE_STATISTICS_SUMMARY_ENTRY_DURATION_S,
    DUE_STATISTICS_SUMMARY_ENTRY_STAGGER_S,
    DUE_STATISTICS_SUMMARY_ENTRY_X_PERCENT,
} from '../constants/due-statistics-summary-animation';
import { ActiveViewType } from '../enums';
import type { IDueDiligenceStatisticsService } from '../interfaces/services';

type TGsapMatchMediaCallback = () => void | (() => void);

type TGsapMatchMedia = {
    add: (query: string, callback: TGsapMatchMediaCallback) => void | (() => void);
    revert: () => void;
};

type TGsapContext = {
    revert: () => void;
};

const mockFromTo = jest.fn();
const mockSet = jest.fn();
const mockContext = jest.fn<(fn: () => void, scope?: unknown) => TGsapContext>();
const mockMatchMedia = jest.fn<() => TGsapMatchMedia>();

jest.mock('gsap', () => ({
    __esModule: true,
    default: {
        fromTo: (...args: unknown[]) => mockFromTo(...args),
        set: (...args: unknown[]) => mockSet(...args),
        context: (fn: () => void, scope?: unknown) => mockContext(fn, scope),
        matchMedia: () => mockMatchMedia(),
    },
}));

jest.mock('../hooks/use-due-diligence-active-view', () => ({
    useDueDiligenceActiveView: () => ({
        activeView: ActiveViewType.DUE_DILIGENCE,
        setActiveView: jest.fn(),
        isTabDisabled: () => false,
    }),
}));

jest.mock('../hooks/useOperationalListFilterQueryState', () => ({
    useOperationalListFilterQueryState: () => ({
        operationalListApiFilters: [],
        modeloScope: 'v2',
        toggleModelo: jest.fn(),
    }),
}));

jest.mock('@tanstack/react-query', () => ({
    useQuery: () => ({
        data: {
            total_oficios: 0,
            total_oficios_v2: 0,
            total_oficios_v1: 0,
            valor_liquido_total: 0,
            oficios_em_deadline: 0,
            tribunais_unicos: 0,
        },
        isLoading: false,
    }),
}));

describe('useViewModelDueDiligenceStatistics entry animation', () => {
    const service: IDueDiligenceStatisticsService = {
        getSummary: jest.fn(async () => ({
            total_oficios: 0,
            total_oficios_v2: 0,
            total_oficios_v1: 0,
            valor_liquido_total: 0,
            oficios_em_deadline: 0,
            tribunais_unicos: 0,
        })),
    };

    beforeEach(() => {
        jest.clearAllMocks();

        const media: TGsapMatchMedia = {
            add: (query, callback) => {
                if (query.includes('prefers-reduced-motion: no-preference')) {
                    return callback();
                }
            },
            revert: jest.fn(),
        };

        mockMatchMedia.mockReturnValue(media);
        mockContext.mockImplementation((fn) => {
            fn();
            return { revert: jest.fn() };
        });
    });

    it('expõe summaryCardsContainerRef e anima cards com xPercent, opacity, blur e stagger', async () => {
        const { useViewModelDueDiligenceStatistics } = await import(
            '../ViewModels/useViewModelDueDiligenceStatistics'
        );

        function StatisticsAnimationHost() {
            const viewModel = useViewModelDueDiligenceStatistics(service);

            return (
                <section
                    ref={viewModel.summaryCardsContainerRef}
                    data-testid="summary-cards-container"
                >
                    <div data-due-statistics-summary-card data-testid="summary-card-1" />
                    <div data-due-statistics-summary-card data-testid="summary-card-2" />
                    <div data-due-statistics-summary-card data-testid="summary-card-3" />
                    <div data-due-statistics-summary-card data-testid="summary-card-4" />
                </section>
            );
        }

        render(<StatisticsAnimationHost />);

        const cards = screen.getAllByTestId(/summary-card-/);

        expect(mockFromTo).toHaveBeenCalledTimes(1);
        expect(mockFromTo).toHaveBeenCalledWith(
            expect.any(Object),
            {
                xPercent: DUE_STATISTICS_SUMMARY_ENTRY_X_PERCENT,
                opacity: 0,
                filter: `blur(${DUE_STATISTICS_SUMMARY_ENTRY_BLUR_PX}px)`,
            },
            expect.objectContaining({
                xPercent: 0,
                opacity: 1,
                filter: 'blur(0px)',
                duration: DUE_STATISTICS_SUMMARY_ENTRY_DURATION_S,
                ease: 'power3.out',
                stagger: DUE_STATISTICS_SUMMARY_ENTRY_STAGGER_S,
                force3D: true,
            }),
        );

        const fromToTarget = mockFromTo.mock.calls[0]?.[0] as NodeListOf<Element>;
        expect(fromToTarget).toHaveLength(cards.length);
        expect(mockSet).not.toHaveBeenCalled();
    });

    it('respeita prefers-reduced-motion sem disparar fromTo', async () => {
        const media: TGsapMatchMedia = {
            add: (query, callback) => {
                if (query.includes('prefers-reduced-motion: reduce')) {
                    return callback();
                }
            },
            revert: jest.fn(),
        };
        mockMatchMedia.mockReturnValue(media);

        const { useViewModelDueDiligenceStatistics } = await import(
            '../ViewModels/useViewModelDueDiligenceStatistics'
        );

        function StatisticsReducedMotionHost() {
            const viewModel = useViewModelDueDiligenceStatistics(service);

            return (
                <section
                    ref={viewModel.summaryCardsContainerRef}
                    data-testid="summary-cards-container-reduced"
                >
                    <div data-due-statistics-summary-card />
                    <div data-due-statistics-summary-card />
                </section>
            );
        }

        render(<StatisticsReducedMotionHost />);

        expect(mockFromTo).not.toHaveBeenCalled();
        expect(mockSet).toHaveBeenCalledWith(
            expect.any(Object),
            {
                xPercent: 0,
                opacity: 1,
                filter: 'blur(0px)',
            },
        );
    });
});

