import { describe, expect, it, jest } from '@jest/globals';
import { renderHook } from '@testing-library/react';
import { QueryKeys } from '@/constants/query-keys';
import { ActiveViewType } from '../enums';
import type {
    IDueDiligenceStatisticsService,
    TDueDiligenceStatisticsSummary,
} from '../interfaces/services';

interface IQueryOptions {
    queryKey: readonly unknown[];
    queryFn: () => Promise<TDueDiligenceStatisticsSummary>;
}

let mockCapturedQueryOptions: IQueryOptions | undefined;

jest.mock('../hooks/use-due-diligence-active-view', () => ({
    useDueDiligenceActiveView: () => ({
        activeView: ActiveViewType.DUE_DILIGENCE,
    }),
}));

const mockToggleModelo = jest.fn();

jest.mock('../hooks/useOperationalListFilterQueryState', () => ({
    useOperationalListFilterQueryState: () => ({
        operationalListApiFilters: [
            { id: 'modelo', label: 'Modelo', value: 'v2' },
            { id: 'broker', label: 'Broker', value: 'ana' },
            { id: 'host', label: 'Host', value: 'faro' },
        ],
        modeloScope: 'v2',
        toggleModelo: mockToggleModelo,
    }),
}));

jest.mock('@tanstack/react-query', () => ({
    useQuery: (options: IQueryOptions) => {
        mockCapturedQueryOptions = options;
        return {
            data: {
                total_oficios: 9,
                total_oficios_v2: 6,
                total_oficios_v1: 3,
                valor_liquido_total: 100_000,
                oficios_em_deadline: 2,
                tribunais_unicos: 4,
            },
            isLoading: false,
        };
    },
}));

describe('useViewModelDueDiligenceStatistics — filtros e modelos', () => {
    it('consulta pelos demais filtros, ignora modelo e expõe os dois totais', async () => {
        const service: IDueDiligenceStatisticsService = {
            getSummary: jest.fn(async () => ({
                total_oficios: 9,
                total_oficios_v2: 6,
                total_oficios_v1: 3,
                valor_liquido_total: 100_000,
                oficios_em_deadline: 2,
                tribunais_unicos: 4,
            })),
        };
        const { useViewModelDueDiligenceStatistics } = await import(
            '../ViewModels/useViewModelDueDiligenceStatistics'
        );

        const { result } = renderHook(() => useViewModelDueDiligenceStatistics(service));

        expect(mockCapturedQueryOptions?.queryKey).toEqual([
            QueryKeys.dueDiligence.listSummary,
            ActiveViewType.DUE_DILIGENCE,
            'and(eq(broker,ana),eq(host,faro))',
        ]);
        await mockCapturedQueryOptions?.queryFn();
        expect(service.getSummary).toHaveBeenCalledWith(
            'and(eq(broker,ana),eq(host,faro))',
        );
        expect(result.current.ui).toMatchObject({
            totalOficios: 9,
            totalOficiosV2: 6,
            totalOficiosV1: 3,
            modeloSelecionado: 'v2',
        });
    });

    it('delega a seleção de modelo para o estado de filtro da listagem', async () => {
        const service: IDueDiligenceStatisticsService = {
            getSummary: jest.fn(async () => ({
                total_oficios: 9,
                total_oficios_v2: 6,
                total_oficios_v1: 3,
                valor_liquido_total: 100_000,
                oficios_em_deadline: 2,
                tribunais_unicos: 4,
            })),
        };
        const { useViewModelDueDiligenceStatistics } = await import(
            '../ViewModels/useViewModelDueDiligenceStatistics'
        );

        const { result } = renderHook(() => useViewModelDueDiligenceStatistics(service));
        result.current.onSelecionarModelo('v1');

        expect(mockToggleModelo).toHaveBeenCalledWith('v1');
    });
});

