import { beforeEach, describe, expect, it, jest } from '@jest/globals';
import { act, renderHook } from '@testing-library/react';
import { QueryKeys } from '@/constants/query-keys';
import { LIQUIDACAO_FUNIL_SUBSTATUS_ORDER } from '../constants/liquidacaoSubstatusFunnel';
import type { ILiquidacaoScreenService } from '../interfaces/services';
import type { Filter } from '@/types/filter';
import type { TLiquidacaoFunilSubstatusCounts } from '../types/liquidacaoKanban';

const mockQueryStates: { liqSubStatus: string | null; page: number } = {
    liqSubStatus: null,
    page: 2,
};

const mockSetQueryStates = jest.fn();
const operationalFilters: { liquidacaoListApiFilters: Filter[] } = {
    liquidacaoListApiFilters: [],
};

const SPEC_FUNIL_COUNTS: TLiquidacaoFunilSubstatusCounts = {
    revisar_card_investimento: 13,
    enviar_investidor: 1,
    analise_investidor: 0,
    agendar_cartorio: 0,
    cartorio_agendado: 1,
    enviar_financeiro: 3,
    juntar_peticao: 0,
};

type TCountsQueryOptions = {
    queryKey: unknown[];
    queryFn: () => Promise<TLiquidacaoFunilSubstatusCounts>;
};

const mockUseQuery = jest.fn((options: TCountsQueryOptions) => ({
    data: SPEC_FUNIL_COUNTS as TLiquidacaoFunilSubstatusCounts | undefined,
    isPending: false,
    queryKey: options.queryKey,
}));

jest.mock('nuqs', () => ({
    parseAsInteger: { withDefault: () => ({}) },
    parseAsString: {},
    useQueryStates: () => [mockQueryStates, mockSetQueryStates],
}));

jest.mock('../hooks/useOperationalListFilterQueryState', () => ({
    useOperationalListFilterQueryState: () => ({
        liquidacaoListApiFilters: operationalFilters.liquidacaoListApiFilters,
    }),
}));

jest.mock('@tanstack/react-query', () => ({
    useQuery: (options: TCountsQueryOptions) => mockUseQuery(options),
}));

function createService(
    counts: TLiquidacaoFunilSubstatusCounts = SPEC_FUNIL_COUNTS,
): ILiquidacaoScreenService {
    return {
        get: jest.fn(),
        getSubstatusCounts: jest.fn(async () => counts),
        reabrirDueDiligence: jest.fn(),
        resetLiquidacaoTimeline: jest.fn(),
    };
}

async function renderViewModel(service: ILiquidacaoScreenService = createService()) {
    const { useViewModelLiquidacaoSubstatusFilter } = await import(
        '../ViewModels/useViewModelLiquidacaoSubstatusFilter'
    );
    return {
        service,
        ...renderHook(() =>
            useViewModelLiquidacaoSubstatusFilter({ liquidacaoScreenService: service }),
        ),
    };
}

describe('useViewModelLiquidacaoSubstatusFilter', () => {
    beforeEach(() => {
        mockQueryStates.liqSubStatus = null;
        mockQueryStates.page = 2;
        mockSetQueryStates.mockClear();
        mockUseQuery.mockClear();
        operationalFilters.liquidacaoListApiFilters = [];
        mockUseQuery.mockImplementation((options: TCountsQueryOptions) => ({
            data: SPEC_FUNIL_COUNTS,
            isPending: false,
            queryKey: options.queryKey,
        }));
    });

    it('expõe os sete chips com os counts reais e zeros preservados', async () => {
        const { result } = await renderViewModel();

        expect(result.current.ui.chips.map((chip) => chip.count)).toEqual([13, 1, 0, 0, 1, 3, 0]);
        expect(result.current.ui.chips).toHaveLength(LIQUIDACAO_FUNIL_SUBSTATUS_ORDER.length);
        expect(result.current.ui.chips[0]?.sub_status).toBe('revisar_card_investimento');
        expect(result.current.ui.chips[0]?.count).toBe(13);
        expect(result.current.ui.selectedSubstatus).toBeNull();
        expect(result.current.constants.chipsCatalog).toEqual(LIQUIDACAO_FUNIL_SUBSTATUS_ORDER);
        expect(result.current.constants).not.toHaveProperty('mockCounts');
        expect(result.current.ui.chips.every((chip) => chip.isSelected === false)).toBe(true);
        expect(result.current.ui.isCountsLoading).toBe(false);
    });

    it('expõe isCountsLoading enquanto o GET de counts ainda está pendente', async () => {
        mockUseQuery.mockImplementation((options: TCountsQueryOptions) => ({
            data: undefined,
            isPending: true,
            queryKey: options.queryKey,
        }));

        const { result } = await renderViewModel();

        expect(result.current.ui.isCountsLoading).toBe(true);
    });

    it('não envia sub_status no GET de counts quando um chip está selecionado', async () => {
        mockQueryStates.liqSubStatus = 'agendar_cartorio';
        operationalFilters.liquidacaoListApiFilters = [
            { id: 'status_liquidacao', label: 'Status', value: 'LIQ_TODOS' },
            { id: 'sub_status', label: 'Sub status', value: 'agendar_cartorio' },
            { id: 'modelo', label: 'Modelo', value: 'v2' },
        ];
        const service = createService();

        const { result } = await renderViewModel(service);
        const queryOptions = mockUseQuery.mock.calls.at(-1)?.[0];

        expect(queryOptions?.queryKey[0]).toBe(QueryKeys.dueDiligence.liquidacaoSubstatusCounts);
        await queryOptions?.queryFn();

        expect(service.getSubstatusCounts).toHaveBeenCalledWith([
            { id: 'status_liquidacao', label: 'Status', value: 'LIQ_TODOS' },
            { id: 'modelo', label: 'Modelo', value: 'v2' },
        ]);
        expect(result.current.ui.selectedSubstatus).toBe('agendar_cartorio');
        expect(result.current.ui.chips.find((chip) => chip.isSelected)?.sub_status).toBe(
            'agendar_cartorio',
        );
        expect(result.current.ui.chips.map((chip) => chip.count)).toEqual([13, 1, 0, 0, 1, 3, 0]);
    });

    it('trata URL vazia ou undefined como ausência de filtro', async () => {
        mockQueryStates.liqSubStatus = '';

        const emptyResult = await renderViewModel();
        expect(emptyResult.result.current.ui.selectedSubstatus).toBeNull();

        mockQueryStates.liqSubStatus = undefined as unknown as null;

        const undefinedResult = await renderViewModel();
        expect(undefinedResult.result.current.ui.selectedSubstatus).toBeNull();
        expect(
            undefinedResult.result.current.ui.chips.every((chip) => chip.isSelected === false),
        ).toBe(true);
    });

    it('marca o chip da etapa 1 quando a URL tem revisar_card_investimento', async () => {
        mockQueryStates.liqSubStatus = 'revisar_card_investimento';

        const { result } = await renderViewModel();

        expect(result.current.ui.selectedSubstatus).toBe('revisar_card_investimento');
        const selectedChip = result.current.ui.chips.find((chip) => chip.isSelected);
        expect(selectedChip?.sub_status).toBe('revisar_card_investimento');
        expect(selectedChip?.count).toBe(13);
    });

    it('ignora slug inválido na URL', async () => {
        mockQueryStates.liqSubStatus = 'aprovado_investidor';

        const { result } = await renderViewModel();

        expect(result.current.ui.selectedSubstatus).toBeNull();
        expect(result.current.ui.chips.every((chip) => chip.isSelected === false)).toBe(true);
    });

    it('aplica o filtro e volta para a primeira página', async () => {
        const { result } = await renderViewModel();

        act(() => {
            result.current.handlers.onSelectSubstatus('enviar_financeiro');
        });

        expect(mockSetQueryStates).toHaveBeenCalledWith({
            liqSubStatus: 'enviar_financeiro',
            page: 1,
        });
    });

    it('limpa o filtro ao clicar no chip já selecionado', async () => {
        mockQueryStates.liqSubStatus = 'juntar_peticao';

        const { result } = await renderViewModel();

        act(() => {
            result.current.handlers.onSelectSubstatus('juntar_peticao');
        });

        expect(mockSetQueryStates).toHaveBeenCalledWith({
            liqSubStatus: null,
            page: 1,
        });
    });
});

