import '@testing-library/jest-dom/jest-globals';
import { beforeEach, describe, expect, it, jest } from '@jest/globals';
import { renderHook, waitFor } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import type { ReactNode } from 'react';

import type { IDueCardsService } from '../interfaces/services';

const mockUseOperationalListFilterQueryState = jest.fn();
const mockPrefetchQuery = jest.fn();

jest.mock('../hooks/useOperationalListFilterQueryState', () => ({
    useOperationalListFilterQueryState: () => mockUseOperationalListFilterQueryState(),
}));

jest.mock('@/store/useDueDiligenceStore', () => ({
    useDueDiligenceStore: (selector: (state: { openObservationSheet: () => void }) => unknown) =>
        selector({ openObservationSheet: jest.fn() }),
}));

jest.mock('next/navigation', () => ({
    useRouter: () => ({ push: jest.fn() }),
}));

jest.mock('../hooks/use-enviar-pos-aquisicao-mutation', () => ({
    useEnviarPosAquisicaoMutation: () => ({ mutate: jest.fn(), isPending: false }),
}));

jest.mock('../hooks/use-avancar-em-liquidacao-mutation', () => ({
    useAvancarEmLiquidacaoMutation: () => ({ mutate: jest.fn(), isPending: false }),
}));

jest.mock('../hooks/use-cessionario-dialog-state', () => ({
    useCessionarioDialogState: () => ({
        isOpen: false,
        open: jest.fn(),
        close: jest.fn(),
        dueId: null,
        patchHandlers: (handlers: unknown) => handlers,
    }),
}));

jest.mock('../hooks/use-escritura-publica-dialog-state', () => ({
    useEscrituraPublicaDialogState: () => ({
        resolveEscrituraStatus: jest.fn(),
    }),
}));

jest.mock('@tanstack/react-query', () => {
    const actual = jest.requireActual<typeof import('@tanstack/react-query')>(
        '@tanstack/react-query',
    );

    return {
        ...actual,
        useQuery: jest.fn(() => ({
            data: {
                count: 24,
                next: '/api/v2/due-diligences/?card=true&page=2',
                previous: null,
                results: [{ id: 'due-1' }],
            },
            isLoading: false,
            isFetching: false,
        })),
        useMutation: jest.fn(() => ({ mutate: jest.fn(), isPending: false })),
    };
});

jest.mock('@/utils/queryClient', () => ({
    __esModule: true,
    default: {
        prefetchQuery: (...args: unknown[]) => mockPrefetchQuery(...args),
    },
}));

function createWrapper(queryClient: QueryClient) {
    return function Wrapper({ children }: { children: ReactNode }) {
        return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>;
    };
}

describe('useViewModelCardsDue prefetch', () => {
    const service: IDueCardsService = {
        get: jest.fn(async () => ({
            count: 24,
            next: '/api/v2/due-diligences/?card=true&page=2',
            previous: null,
            results: [{ id: 'due-1' }],
        })),
    };

    beforeEach(() => {
        jest.clearAllMocks();
        mockUseOperationalListFilterQueryState.mockReturnValue({
            page: 1,
            setPage: jest.fn(),
            dueListApiFilters: { filter: '' },
            listQueryFingerprint: 'fp-1',
        });
        mockPrefetchQuery.mockResolvedValue(undefined);

        Object.defineProperty(window, 'requestIdleCallback', {
            configurable: true,
            writable: true,
            value: undefined,
        });
    });

    it('nao dispara prefetch imediato da pagina 2 no mount', async () => {
        jest.useFakeTimers();
        const queryClient = new QueryClient({
            defaultOptions: { queries: { retry: false } },
        });

        const { useViewModelCardsDue } = await import('../ViewModels/useViewModelCardsDue');

        renderHook(() => useViewModelCardsDue(service), {
            wrapper: createWrapper(queryClient),
        });

        await waitFor(() => {
            expect(service.get).not.toHaveBeenCalled();
        });

        expect(mockPrefetchQuery).not.toHaveBeenCalled();

        jest.advanceTimersByTime(1500);

        await waitFor(() => {
            expect(mockPrefetchQuery).toHaveBeenCalledTimes(1);
        });

        jest.useRealTimers();
    });
});

