import { beforeEach, describe, expect, it, jest } from '@jest/globals';
import { renderHook } from '@testing-library/react';
import type { Filter } from '@/types/filter';

const queryState = {
    page: 1,
    liquidacaoListApiFilters: [] as Filter[],
    listQueryFingerprint: '',
};

jest.mock('../hooks/useOperationalListFilterQueryState', () => ({
    useOperationalListFilterQueryState: () => ({
        page: queryState.page,
        setPage: jest.fn(),
        liquidacaoListApiFilters: queryState.liquidacaoListApiFilters,
        listQueryFingerprint: queryState.listQueryFingerprint,
    }),
}));

jest.mock('@/store/useDueDiligenceStore', () => ({
    useDueDiligenceStore: Object.assign(
        (selector: (state: { openObservationSheet: () => void }) => unknown) =>
            selector({ openObservationSheet: jest.fn() }),
        { getState: () => ({ idwallStatusOverrides: {}, openIdwallDialog: jest.fn(), openEscrituraDialog: jest.fn() }) },
    ),
}));

jest.mock('next/navigation', () => ({
    useRouter: () => ({ push: jest.fn() }),
}));

jest.mock('../hooks/use-avancar-em-liquidacao-mutation', () => ({
    useAvancarEmLiquidacaoMutation: () => ({
        mutateAsync: jest.fn(),
        isLoadingForDueId: () => false,
    }),
}));

jest.mock('../hooks/use-enviar-pos-aquisicao-mutation', () => ({
    useEnviarPosAquisicaoMutation: () => ({
        mutateAsync: jest.fn(),
        isLoadingForDueId: () => false,
    }),
}));

jest.mock('../hooks/use-escritura-publica-dialog-state', () => ({
    useEscrituraPublicaDialogState: () => ({
        resolveEscrituraStatus: jest.fn(),
    }),
}));

jest.mock('../hooks/use-cessionario-dialog-state', () => ({
    useCessionarioDialogState: () => ({
        patchHandlers: (handlers: unknown) => handlers,
        getLista: jest.fn(),
        getTotalPctCessaoForItem: jest.fn(),
    }),
}));

let capturedQuery:
    | {
          queryKey: unknown[];
          queryFn: () => Promise<unknown>;
      }
    | undefined;

jest.mock('@/utils/queryClient', () => ({
    __esModule: true,
    default: { invalidateQueries: jest.fn() },
}));

jest.mock('@tanstack/react-query', () => ({
    QueryClient: class QueryClient {},
    useQuery: (options: { queryKey: unknown[]; queryFn: () => Promise<unknown> }) => {
        capturedQuery = options;
        return { data: undefined, isLoading: true, isFetching: false };
    },
    useMutation: () => ({
        mutateAsync: jest.fn(),
        isPending: false,
    }),
}));

const mockGet = jest.fn();

async function renderCardsViewModel() {
    const { useViewModelCardsLiquidacao } = await import(
        '../ViewModels/useViewModelCardsLiquidacao'
    );

    return renderHook(() =>
        useViewModelCardsLiquidacao({
            service: {
                get: mockGet,
                getSubstatusCounts: jest.fn(),
                reabrirDueDiligence: jest.fn(),
                resetLiquidacaoTimeline: jest.fn(),
            },
            dueCardsService: {} as never,
            cessionarioService: {} as never,
        }),
    );
}

describe('useViewModelCardsLiquidacao — consumo do filtro de sub_status', () => {
    beforeEach(() => {
        capturedQuery = undefined;
        mockGet.mockReset();
        mockGet.mockResolvedValue({ results: [], count: 0, next: null, previous: null });
        queryState.page = 1;
        queryState.liquidacaoListApiFilters = [];
        queryState.listQueryFingerprint = '';
    });

    it('repassa o sub_status do hook compartilhado na query dos cards', async () => {
        queryState.liquidacaoListApiFilters = [
            { id: 'sub_status', label: 'Sub status', value: 'agendar_cartorio' },
        ];
        queryState.listQueryFingerprint = '{"liquidacaoSubstatus":"agendar_cartorio"}';

        await renderCardsViewModel();

        expect(capturedQuery?.queryKey).toEqual([
            'due-diligence',
            'liquidacao',
            'items',
            1,
            queryState.listQueryFingerprint,
        ]);

        await capturedQuery?.queryFn();

        expect(mockGet).toHaveBeenCalledWith(1, queryState.liquidacaoListApiFilters);
    });

    it('consulta os cards sem sub_status quando o hook não envia o filtro', async () => {
        queryState.liquidacaoListApiFilters = [
            { id: 'status_liquidacao', label: 'Status Liquidacao', value: 'LIQ_TODOS' },
        ];
        queryState.listQueryFingerprint = '{"liquidacaoSubstatus":null}';

        await renderCardsViewModel();
        await capturedQuery?.queryFn();

        expect(capturedQuery?.queryKey[4]).toBe(queryState.listQueryFingerprint);
        expect(mockGet).toHaveBeenCalledWith(1, queryState.liquidacaoListApiFilters);
        expect(
            queryState.liquidacaoListApiFilters.some((filter) => filter.id === 'sub_status'),
        ).toBe(false);
    });
});

