import '@testing-library/jest-dom/jest-globals';
import { describe, expect, it, jest, beforeEach } from '@jest/globals';
import { renderHook, waitFor } from '@testing-library/react';
import type { Filter } from '@/types/filter';
import type { IArquivamentosScreenService } from '../interfaces/services';
import { CessionarioService } from '../services/CessionarioService';

const mockOperationalFilters: Filter[] = [
    { id: 'credor', label: 'Credor', value: 'Maria' },
    { id: 'loa', label: 'LOA', value: '2024' },
];

const mockSetPage = jest.fn();

jest.mock('../hooks/useOperationalListFilterQueryState', () => ({
    useOperationalListFilterQueryState: () => ({
        page: 2,
        setPage: mockSetPage,
        operationalListApiFilters: mockOperationalFilters,
        listQueryFingerprint: '{"operational":"filters"}',
    }),
}));

jest.mock('next/navigation', () => ({
    useRouter: () => ({ push: jest.fn() }),
}));

jest.mock('@/store/useDueDiligenceStore', () => ({
    useDueDiligenceStore: (selector: (state: { openObservationSheet: jest.Mock }) => unknown) =>
        selector({ openObservationSheet: jest.fn() }),
}));

jest.mock('../hooks/use-cessionario-dialog-state', () => ({
    useCessionarioDialogState: () => ({
        getLista: jest.fn(),
        getTotalPctCessaoForItem: jest.fn(),
        patchHandlers: (handlers: unknown) => handlers,
    }),
}));

jest.mock('../hooks/use-escritura-publica-dialog-state', () => ({
    useEscrituraPublicaDialogState: () => ({
        resolveEscrituraStatus: jest.fn(),
    }),
}));

jest.mock('@/utils/queryClient', () => ({
    __esModule: true,
    default: {
        prefetchQuery: jest.fn(),
        invalidateQueries: jest.fn(),
    },
}));

jest.mock('@tanstack/react-query', () => ({
    useQuery: ({
        queryFn,
    }: {
        queryFn: () => Promise<{
            count: number;
            next: null;
            previous: null;
            results: [];
        }>;
    }) => {
        void queryFn();

        return {
            data: {
                count: 0,
                next: null,
                previous: null,
                results: [],
            },
            isLoading: false,
            isFetching: false,
        };
    },
}));

describe('useViewModelArquivamentosScreen', () => {
    beforeEach(() => {
        mockSetPage.mockClear();
    });

    it('consulta arquivados com filtros operacionais e paginação compartilhada', async () => {
        const get = jest.fn(async () => ({
            count: 0,
            next: null,
            previous: null,
            results: [],
        }));

        const service: IArquivamentosScreenService = { get };
        const cessionarioService = {} as CessionarioService;

        const { useViewModelArquivamentosScreen } =
            await import('../ViewModels/useViewModelArquivamentosScreen');

        const { result } = renderHook(() =>
            useViewModelArquivamentosScreen({ service, cessionarioService }),
        );

        await waitFor(() => {
            expect(get.mock.calls).toEqual([[2, mockOperationalFilters]]);
        });

        expect(result.current.page).toBe(2);
        expect(result.current.filteredItems).toEqual([]);
        expect(result.current.totalItems).toBe(0);
    });
});

