import { beforeEach, describe, expect, it, jest } from '@jest/globals';
import { act, renderHook } from '@testing-library/react';
import type { Filter } from '@/types/filter';

const mockQueryStates: Record<string, unknown> = {
    filter: 'TODOS',
    liqFilter: 'TODOS',
    modelo: 'v2',
    loa: null,
    credor: null,
    broker: null,
    priority_level: null,
    responsavel_scope: null,
    investidor_scope: null,
    investidor: null,
    esfera: null,
    coordenador: null,
    host: null,
    liqSubStatus: null,
    page: 1,
};

const withDefaultSpy = jest.fn();
const mockSetQueryStates = jest.fn();

jest.mock('nuqs', () => ({
    parseAsInteger: { withDefault: () => ({}) },
    parseAsString: {
        withDefault: (value: unknown) => {
            withDefaultSpy(value);
            return {};
        },
    },
    parseAsStringEnum: () => ({ withDefault: () => ({}) }),
    useQueryStates: () => [mockQueryStates, mockSetQueryStates],
}));

jest.mock('@/store/userInfo', () => ({
    useUserInfoStore: (selector: (state: { data: { username: string; host: string } }) => unknown) =>
        selector({ data: { username: 'analista', host: 'celer' } }),
}));

function modeloFilterOf(filters: Filter[]): Filter | undefined {
    return filters.find((filter) => filter.id === 'modelo');
}

async function renderFilters() {
    const { useOperationalListFilterQueryState } = await import(
        '../hooks/useOperationalListFilterQueryState'
    );
    return renderHook(() => useOperationalListFilterQueryState());
}

describe('useOperationalListFilterQueryState — escopo de modelo', () => {
    beforeEach(() => {
        withDefaultSpy.mockClear();
        mockSetQueryStates.mockClear();
    });

    it('registra v2 como padrão do parâmetro modelo', async () => {
        await renderFilters();

        expect(withDefaultSpy).toHaveBeenCalledWith('v2');
    });

    it('envia o modelo v2 para a listagem e para os filtros operacionais', async () => {
        mockQueryStates.modelo = 'v2';

        const { result } = await renderFilters();

        expect(modeloFilterOf(result.current.dueListApiFilters)?.value).toBe('v2');
        expect(modeloFilterOf(result.current.operationalListApiFilters)?.value).toBe('v2');
        expect(modeloFilterOf(result.current.liquidacaoListApiFilters)?.value).toBe('v2');
    });

    it('mantém o legado v1 quando escolhido', async () => {
        mockQueryStates.modelo = 'v1';

        const { result } = await renderFilters();

        expect(modeloFilterOf(result.current.dueListApiFilters)?.value).toBe('v1');
    });

    it('não envia filtro de modelo na opção Todos os modelos', async () => {
        mockQueryStates.modelo = 'all';

        const { result } = await renderFilters();

        expect(modeloFilterOf(result.current.dueListApiFilters)).toBeUndefined();
        expect(modeloFilterOf(result.current.operationalListApiFilters)).toBeUndefined();
        expect(modeloFilterOf(result.current.liquidacaoListApiFilters)).toBeUndefined();
    });

    it('aplica o modelo escolhido e volta para a primeira página', async () => {
        mockQueryStates.modelo = 'v2';

        const { result } = await renderFilters();
        act(() => result.current.toggleModelo('v1'));

        expect(mockSetQueryStates).toHaveBeenCalledWith({ modelo: 'v1', page: 1 });
    });

    it('limpa o filtro ao clicar no modelo já selecionado', async () => {
        mockQueryStates.modelo = 'v2';

        const { result } = await renderFilters();
        act(() => result.current.toggleModelo('v2'));

        expect(mockSetQueryStates).toHaveBeenCalledWith({ modelo: 'all', page: 1 });
    });

    it('expõe o modelo ativo e trata Todos os modelos como ausência de escopo', async () => {
        mockQueryStates.modelo = 'all';

        const { result } = await renderFilters();

        expect(result.current.modeloScope).toBeNull();
    });
});

