import { beforeEach, describe, expect, it, jest } from '@jest/globals';
import { renderHook } from '@testing-library/react';
import type { Filter } from '@/types/filter';
import { filtersToRQLParams } from '@/utils/rql';
import { LIQUIDACAO_FUNIL_SUBSTATUS_ORDER } from '../constants/liquidacaoSubstatusFunnel';
import { STATUS_LIQUIDACAO_QUERY_LIQ_TODOS } from '../services/LiquidacaoScreenService';

const mockQueryStates: Record<string, unknown> = {
    filter: 'TODOS',
    liqFilter: 'TODOS',
    modelo: 'v2',
    loa: null,
    credor: null,
    broker: null,
    priority_level: null,
    responsavel_scope: null,
    investidor_scope: null,
    investidor: null,
    esfera: null,
    coordenador: null,
    host: null,
    liqSubStatus: null,
    page: 1,
};

jest.mock('nuqs', () => ({
    parseAsInteger: { withDefault: () => ({}) },
    parseAsString: { withDefault: () => ({}) },
    parseAsStringEnum: () => ({ withDefault: () => ({}) }),
    useQueryStates: () => [mockQueryStates, jest.fn()],
}));

jest.mock('@/store/userInfo', () => ({
    useUserInfoStore: (selector: (state: { data: { username: string; host: string } }) => unknown) =>
        selector({ data: { username: 'analista', host: 'celer' } }),
}));

function filterOf(filters: Filter[], id: string): Filter | undefined {
    return filters.find((filter) => filter.id === id);
}

async function renderFilters() {
    const { useOperationalListFilterQueryState } = await import(
        '../hooks/useOperationalListFilterQueryState'
    );
    return renderHook(() => useOperationalListFilterQueryState());
}

describe('useOperationalListFilterQueryState — sub_status do funil', () => {
    beforeEach(() => {
        mockQueryStates.liqSubStatus = null;
        mockQueryStates.liqFilter = 'TODOS';
        mockQueryStates.modelo = 'v2';
        mockQueryStates.host = null;
    });

    it('não envia sub_status quando o param está ausente, vazio ou undefined', async () => {
        const absent = await renderFilters();
        expect(filterOf(absent.result.current.liquidacaoListApiFilters, 'sub_status')).toBeUndefined();

        mockQueryStates.liqSubStatus = '';
        const empty = await renderFilters();
        expect(filterOf(empty.result.current.liquidacaoListApiFilters, 'sub_status')).toBeUndefined();

        mockQueryStates.liqSubStatus = undefined;
        const missing = await renderFilters();
        expect(filterOf(missing.result.current.liquidacaoListApiFilters, 'sub_status')).toBeUndefined();
        expect(missing.result.current.listQueryFingerprint).not.toContain('agendar_cartorio');
    });

    it('anexa cada slug do funil só na lista de liquidação e soma com os filtros atuais', async () => {
        for (const slug of LIQUIDACAO_FUNIL_SUBSTATUS_ORDER) {
            mockQueryStates.liqSubStatus = slug;

            const { result } = await renderFilters();
            const liquidacaoFilters = result.current.liquidacaoListApiFilters;

            expect(filterOf(liquidacaoFilters, 'sub_status')?.value).toBe(slug);
            expect(filterOf(liquidacaoFilters, 'status_liquidacao')?.value).toBe(
                STATUS_LIQUIDACAO_QUERY_LIQ_TODOS,
            );
            expect(filterOf(liquidacaoFilters, 'modelo')?.value).toBe('v2');
            expect(filterOf(result.current.dueListApiFilters, 'sub_status')).toBeUndefined();
            expect(filterOf(result.current.operationalListApiFilters, 'sub_status')).toBeUndefined();
            expect(result.current.listQueryFingerprint).toContain(slug);

            const { filter } = filtersToRQLParams(liquidacaoFilters);
            expect(filter).toContain(`eq(sub_status,${slug})`);
            expect(filter).toContain(`eq(status_liquidacao,${STATUS_LIQUIDACAO_QUERY_LIQ_TODOS})`);
            expect(filter).toContain('eq(modelo,v2)');
        }
    });

    it('ignora slug inválido e não muda o RQL da lista', async () => {
        mockQueryStates.liqSubStatus = 'aprovado_investidor';

        const { result } = await renderFilters();
        const { filter } = filtersToRQLParams(result.current.liquidacaoListApiFilters);

        expect(filterOf(result.current.liquidacaoListApiFilters, 'sub_status')).toBeUndefined();
        expect(result.current.listQueryFingerprint).not.toContain('aprovado_investidor');
        expect(filter).not.toContain('sub_status');
        expect(filter).toContain(`eq(status_liquidacao,${STATUS_LIQUIDACAO_QUERY_LIQ_TODOS})`);
    });
});

