import { beforeEach, describe, expect, it, jest } from '@jest/globals';
import { act, renderHook } from '@testing-library/react';
import type { Filter } from '@/types/filter';

const mockQueryStates: Record<string, unknown> = {
    filter: 'TODOS',
    liqFilter: 'TODOS',
    modelo: 'v2',
    loa: null,
    credor: null,
    broker: null,
    priority_level: null,
    responsavel_scope: null,
    investidor_scope: null,
    investidor: null,
    esfera: null,
    coordenador: null,
    host: null,
    liqSubStatus: null,
    page: 1,
    dataView: 'cards',
};

const mockSetQueryStates = jest.fn();

jest.mock('nuqs', () => ({
    parseAsInteger: { withDefault: () => ({}) },
    parseAsString: { withDefault: () => ({}) },
    parseAsStringEnum: () => ({ withDefault: () => ({}) }),
    useQueryStates: () => [mockQueryStates, mockSetQueryStates],
}));

jest.mock('@/store/userInfo', () => ({
    useUserInfoStore: (selector: (state: { data: { username: string; host: string } }) => unknown) =>
        selector({ data: { username: 'analista', host: 'celer' } }),
}));

function filterOf(filters: Filter[], id: string): Filter | undefined {
    return filters.find((filter) => filter.id === id);
}

async function renderFilters() {
    const { useOperationalListFilterQueryState } = await import(
        '../hooks/useOperationalListFilterQueryState'
    );
    return renderHook(() => useOperationalListFilterQueryState());
}

describe('useOperationalListFilterQueryState — dataView happy path', () => {
    beforeEach(() => {
        mockQueryStates.dataView = 'cards';
        mockQueryStates.page = 1;
        mockQueryStates.credor = null;
        mockSetQueryStates.mockClear();
    });

    it('expõe cards como default e não inclui dataView no fingerprint da listagem', async () => {
        mockQueryStates.dataView = undefined;

        const { result } = await renderFilters();

        expect(result.current.viewMode).toBe('cards');
        expect(result.current.listQueryFingerprint).not.toContain('kanban');
        expect(result.current.listQueryFingerprint).not.toContain('dataView');
        expect(result.current.listQueryFingerprint).not.toContain('"view"');
    });

    it('expõe kanban quando dataView está na URL', async () => {
        mockQueryStates.dataView = 'kanban';

        const { result } = await renderFilters();

        expect(result.current.viewMode).toBe('kanban');
        expect(result.current.listQueryFingerprint).not.toContain('kanban');
    });

    it('expõe crm quando dataView está na URL e não inclui o modo no fingerprint', async () => {
        mockQueryStates.dataView = 'crm';

        const { result } = await renderFilters();

        expect(result.current.viewMode).toBe('crm');
        expect(result.current.listQueryFingerprint).not.toContain('crm');
        expect(result.current.listQueryFingerprint).not.toContain('dataView');
    });

    it('persiste kanban na URL ao alternar o switcher', async () => {
        const { result } = await renderFilters();

        act(() => result.current.setViewMode('kanban'));

        expect(mockSetQueryStates).toHaveBeenCalledWith({ dataView: 'kanban' });
    });

    it('volta para cards na URL sem alterar página', async () => {
        mockQueryStates.dataView = 'kanban';

        const { result } = await renderFilters();

        act(() => result.current.setViewMode('cards'));

        expect(mockSetQueryStates).toHaveBeenCalledWith({ dataView: 'cards' });
        expect(mockSetQueryStates).not.toHaveBeenCalledWith(
            expect.objectContaining({ page: expect.anything() }),
        );
    });

    it('persiste crm na URL sem limpar filtros operacionais nem parâmetros crm*', async () => {
        mockQueryStates.credor = 'União';
        mockQueryStates.page = 3;

        const { result } = await renderFilters();

        act(() => result.current.setViewMode('crm'));

        expect(mockSetQueryStates).toHaveBeenCalledWith({ dataView: 'crm' });
        expect(mockSetQueryStates).not.toHaveBeenCalledWith(
            expect.objectContaining({ credor: expect.anything() }),
        );
        expect(mockSetQueryStates).not.toHaveBeenCalledWith(
            expect.objectContaining({ crmStatus: expect.anything() }),
        );
    });

    it('volta de crm para cards sem limpar parâmetros crm*', async () => {
        mockQueryStates.dataView = 'crm';

        const { result } = await renderFilters();

        act(() => result.current.setViewMode('cards'));

        expect(mockSetQueryStates).toHaveBeenCalledWith({ dataView: 'cards' });
        expect(mockSetQueryStates.mock.calls[0]?.[0]).toEqual({ dataView: 'cards' });
    });
});

describe('useOperationalListFilterQueryState — dataView falha', () => {
    beforeEach(() => {
        mockQueryStates.dataView = 'cards';
        mockQueryStates.page = 1;
        mockQueryStates.credor = null;
        mockSetQueryStates.mockClear();
    });

    it('cai em cards quando dataView é null ou undefined', async () => {
        mockQueryStates.dataView = null;
        expect((await renderFilters()).result.current.viewMode).toBe('cards');

        mockQueryStates.dataView = undefined;
        expect((await renderFilters()).result.current.viewMode).toBe('cards');
    });

    it('não vaza o modo de visualização para os filtros da API', async () => {
        mockQueryStates.dataView = 'kanban';

        const { result } = await renderFilters();

        expect(filterOf(result.current.liquidacaoListApiFilters, 'dataView')).toBeUndefined();
        expect(filterOf(result.current.liquidacaoListApiFilters, 'view')).toBeUndefined();
        expect(filterOf(result.current.dueListApiFilters, 'dataView')).toBeUndefined();
        expect(filterOf(result.current.operationalListApiFilters, 'dataView')).toBeUndefined();
    });

    it('não vaza dataView=crm para os filtros da API', async () => {
        mockQueryStates.dataView = 'crm';

        const { result } = await renderFilters();

        expect(filterOf(result.current.liquidacaoListApiFilters, 'dataView')).toBeUndefined();
        expect(filterOf(result.current.dueListApiFilters, 'dataView')).toBeUndefined();
        expect(filterOf(result.current.operationalListApiFilters, 'dataView')).toBeUndefined();
    });
});

