describe('OperationalListExportActions', () => {
    beforeEach(() => {
        queryClient.clear();
        jest.clearAllMocks();
    });

    it('renderiza Baixar relatórios no modo liquidação', async () => {
        const { OperationalListExportActions } = await import(
            '../Views/shared/OperationalListExportActions'
        );

        renderWithQueryClient(<OperationalListExportActions dueProcess="liquidation" />);

        const trigger = screen.getByRole('button', { name: /baixar relatórios/i });
