        ).toBeInTheDocument();
    });

    it('exporta a planilha no modelo da URL sem perguntar Due 2.0 ou Ambas', async () => {
        const { OperationalListExportActions } = await import(
            '../Views/shared/OperationalListExportActions'
        );
        const { exportDueDiligenceCards } = await import('@/services/due-diligence');
        const user = userEvent.setup();

        renderWithQueryClient(<OperationalListExportActions dueProcess="due-diligence" />);
