                    { id: 'modelo', label: 'Modelo', value: 'v2' },
                ],
                'due-diligence',
                'backend-allow-list',
            );
        });
        expect(screen.queryByText(/qual modelo exportar/i)).not.toBeInTheDocument();
        expect(screen.queryByRole('menuitem', { name: /^ambas$/i })).not.toBeInTheDocument();
    });

    it('exporta arquivados com status=ARQUIVADA e só planilha dos cards', async () => {
        const { OperationalListExportActions } = await import(
            '../Views/shared/OperationalListExportActions'
        );
        const { exportDueDiligenceCards } = await import('@/services/due-diligence');
        const user = userEvent.setup();

        renderWithQueryClient(
            <OperationalListExportActions dueProcess="due-diligence" statusScope="archived" />,
        );
        await user.click(screen.getByRole('button', { name: /baixar planilha dos cards/i }));

        await waitFor(() => {
            expect(exportDueDiligenceCards).toHaveBeenCalledWith(
                [
                    { id: 'loa', label: 'LOA', value: '2028' },
                    { id: 'modelo', label: 'Modelo', value: 'v2' },
                ],
                'due-diligence',
                'archived',
            );
        });
        expect(screen.queryByText(/relatório strata/i)).not.toBeInTheDocument();
        expect(screen.queryByText(/cedentes/i)).not.toBeInTheDocument();
    });
});

