import { beforeEach, describe, expect, it, jest } from '@jest/globals';
import '@testing-library/jest-dom/jest-globals';
import { render, screen } from '@testing-library/react';
import { readFileSync } from 'node:fs';
import path from 'node:path';

jest.mock('gsap', () => ({
    __esModule: true,
    default: {
        fromTo: jest.fn(),
        set: jest.fn(),
        context: (fn: () => void) => {
            fn();
            return { revert: jest.fn() };
        },
        matchMedia: () => ({
            add: (_query: string, callback: () => void | (() => void)) => callback(),
            revert: jest.fn(),
        }),
    },
}));

jest.mock(
    '@/components/Juridico/DueDiligence2/ViewModels/useViewModelDueDiligenceStatistics',
    () => ({
        useViewModelDueDiligenceStatistics: () => ({
            summaryCardsContainerRef: { current: null },
            onSelecionarModelo: jest.fn(),
            ui: {
                totalOficios: 10,
                totalOficiosV2: 7,
                totalOficiosV1: 3,
                modeloSelecionado: 'v2',
                valorLiquidoTotal: 50_000,
                oficiosEmDeadline: 2,
                tribunaisUnicos: 3,
                isLoading: false,
            },
        }),
    }),
);

jest.mock('@/components/Juridico/DueDiligence2/Views/LiquidacaoScreen/LiquidacaoSubstatusFilterSection', () => ({
    LiquidacaoSubstatusFilterSection: ({ disabled }: { disabled?: boolean }) => (
        <div
            data-testid="liquidacao-substatus-filter-view"
            data-disabled={disabled ? 'true' : 'false'}
        >
            Funil
        </div>
    ),
}));

jest.mock('@/components/Juridico/DueDiligence2/Views/LiquidacaoScreen/LiquidacaoFilterView', () => ({
    LiquidacaoFilterView: () => <div data-testid="liquidacao-filter-view">Filtros</div>,
}));

const mockViewMode: { current: 'cards' | 'kanban' | 'crm' } = { current: 'cards' };

jest.mock('@/components/Juridico/DueDiligence2/hooks/useOperationalListFilterQueryState', () => ({
    useOperationalListFilterQueryState: () => ({
        viewMode: mockViewMode.current,
        setViewMode: jest.fn(),
    }),
}));

jest.mock('next/dynamic', () => ({
    __esModule: true,
    default: (loader: () => Promise<unknown>) => {
        const loaderSource = String(loader);
        if (loaderSource.includes('LiquidacaoCrmView')) {
            return function LiquidacaoCrmViewStub() {
                return <div data-testid="liquidacao-crm-view">CRM</div>;
            };
        }

        return function LiquidacaoSubstatusKanbanViewStub() {
            return <div data-testid="liquidacao-substatus-kanban-view">Kanban</div>;
        };
    },
}));

jest.mock('@/components/Juridico/DueDiligence2/Views/LiquidacaoScreen/LiquidacaoCardsView', () => ({
    LiquidacaoCardsView: () => <div data-testid="liquidacao-cards-view">Cards</div>,
}));

async function renderScreen() {
    const { LiquidacaoScreenView } = await import('../Views/LiquidacaoScreen');
    return render(<LiquidacaoScreenView />);
}

describe('LiquidacaoScreenView', () => {
    beforeEach(() => {
        mockViewMode.current = 'cards';
    });

    it('renderiza summary antes dos filtros e dos cards', async () => {
        const { container } = await renderScreen();

        expect(screen.getByLabelText('Resumo de ofícios')).toBeInTheDocument();
        expect(screen.getByText('Total de Ofícios')).toBeInTheDocument();
        expect(screen.getByTestId('liquidacao-filter-view')).toBeInTheDocument();
        expect(screen.getByTestId('liquidacao-cards-view')).toBeInTheDocument();

        expect(screen.getByTestId('liquidacao-substatus-filter-view')).toBeInTheDocument();

        const colSpans = container.querySelectorAll('.col-span-full');
        expect(colSpans.length).toBeGreaterThanOrEqual(4);
        expect(colSpans[0]?.querySelector('[aria-label="Resumo de ofícios"]')).toBeTruthy();
        expect(colSpans[1]?.querySelector('[data-testid="liquidacao-filter-view"]')).toBeTruthy();
        expect(colSpans[2]?.querySelector('[data-testid="liquidacao-substatus-filter-view"]')).toBeTruthy();
        expect(colSpans[3]?.querySelector('[data-testid="liquidacao-cards-view"]')).toBeTruthy();
        expect(screen.getByTestId('liquidacao-filter-view').closest('[data-testid="operational-filters-card"]')).toBeTruthy();

        const funnel = screen.getByTestId('liquidacao-substatus-filter-view');
        const filtersCard = screen.getByTestId('operational-filters-card');
        const cards = screen.getByTestId('liquidacao-cards-view');
        expect(filtersCard.compareDocumentPosition(funnel) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
        expect(funnel.compareDocumentPosition(cards) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
        expect(screen.queryByTestId('liquidacao-substatus-kanban-view')).not.toBeInTheDocument();
        expect(screen.queryByTestId('liquidacao-crm-view')).not.toBeInTheDocument();
        expect(screen.getByTestId('liquidacao-substatus-filter-view')).toHaveAttribute(
            'data-disabled',
            'false',
        );
    });

    it('com dataView=kanban renderiza o board e oculta a listagem paginada', async () => {
        mockViewMode.current = 'kanban';

        const { container } = await renderScreen();

        expect(screen.getByTestId('liquidacao-substatus-kanban-view')).toBeInTheDocument();
        expect(screen.queryByTestId('liquidacao-cards-view')).not.toBeInTheDocument();
        expect(screen.getByTestId('liquidacao-filter-view')).toBeInTheDocument();
        expect(screen.getByTestId('liquidacao-substatus-filter-view')).toBeInTheDocument();

        const colSpans = container.querySelectorAll('.col-span-full');
        expect(colSpans[3]?.querySelector('[data-testid="liquidacao-substatus-kanban-view"]')).toBeTruthy();
        expect(screen.queryByTestId('liquidacao-crm-view')).not.toBeInTheDocument();
        expect(screen.getByTestId('liquidacao-substatus-filter-view')).toHaveAttribute(
            'data-disabled',
            'false',
        );
    });

    it('com dataView=crm renderiza só a workspace CRM e desabilita o funil', async () => {
        mockViewMode.current = 'crm';

        const { container } = await renderScreen();

        expect(screen.getByTestId('liquidacao-crm-view')).toBeInTheDocument();
        expect(screen.queryByTestId('liquidacao-cards-view')).not.toBeInTheDocument();
        expect(screen.queryByTestId('liquidacao-substatus-kanban-view')).not.toBeInTheDocument();
        expect(screen.getByTestId('liquidacao-filter-view')).toBeInTheDocument();
        expect(screen.getByTestId('liquidacao-substatus-filter-view')).toBeInTheDocument();
        expect(screen.getByTestId('liquidacao-substatus-filter-view')).toHaveAttribute(
            'data-disabled',
            'true',
        );

        const colSpans = container.querySelectorAll('.col-span-full');
        expect(colSpans[3]?.querySelector('[data-testid="liquidacao-crm-view"]')).toBeTruthy();
    });

    it('desmonta a View CRM ao voltar para Cards', async () => {
        mockViewMode.current = 'crm';

        const { LiquidacaoScreenView } = await import('../Views/LiquidacaoScreen');
        const { rerender } = render(<LiquidacaoScreenView />);
        expect(screen.getByTestId('liquidacao-crm-view')).toBeInTheDocument();

        mockViewMode.current = 'cards';
        rerender(<LiquidacaoScreenView />);

        expect(screen.queryByTestId('liquidacao-crm-view')).not.toBeInTheDocument();
        expect(screen.getByTestId('liquidacao-cards-view')).toBeInTheDocument();
        expect(screen.getByTestId('liquidacao-substatus-filter-view')).toHaveAttribute(
            'data-disabled',
            'false',
        );
    });

    it('carrega a View CRM via next/dynamic com ssr desligado', () => {
        const source = readFileSync(
            path.join(__dirname, '../Views/LiquidacaoScreen/index.tsx'),
            'utf8',
        );

        expect(source).toContain("import('./LiquidacaoCrmView')");
        expect(source).toContain('ssr: false');
        expect(source).not.toMatch(/import \{ LiquidacaoCrmView \}/);
        expect(source).toContain('switch (viewMode)');
        expect(source).not.toContain('isCrmView ?');
    });
});

