import { beforeEach, describe, expect, it, jest } from '@jest/globals';
import '@testing-library/jest-dom/jest-globals';
import { fireEvent, render, screen } from '@testing-library/react';
import type { ReactNode } from 'react';

const mockSetViewMode = jest.fn();
let mockViewMode: 'cards' | 'kanban' | 'crm' = 'cards';

jest.mock('../hooks/useOperationalListFilterQueryState', () => ({
    useOperationalListFilterQueryState: () => ({
        viewMode: mockViewMode,
        setViewMode: mockSetViewMode,
    }),
}));

jest.mock('../ViewModels/useViewModelDiligenceFilter', () => ({
    useViewModelDiligenceFilter: () => ({ fieldHandlers: {} }),
}));

jest.mock('../Views/shared/OperationalFilterGridView', () => ({
    OperationalFilterGridView: ({
        headerActions,
        disabled,
    }: {
        headerActions: ReactNode;
        disabled?: boolean;
    }) => (
        <div
            data-testid="liquidacao-filter-header-actions"
            data-disabled={disabled ? 'true' : 'false'}
        >
            {headerActions}
        </div>
    ),
}));

jest.mock('../Views/shared/OperationalListExportActions', () => ({
    OperationalListExportActions: () => <button type="button">Baixar relatórios</button>,
}));

jest.mock('@/app/crm/gerencial-broker/_constants/colors', () => ({
    COLORS: {
        brand: '#2563eb',
        border: '#243044',
        card: '#ffffff',
    },
    withAlpha: (color: string) => color,
}));

async function renderFilterView() {
    const { LiquidacaoFilterView } = await import(
        '../Views/LiquidacaoScreen/LiquidacaoFilterView'
    );
    return render(<LiquidacaoFilterView />);
}

describe('LiquidacaoFilterView — switcher happy path', () => {
    beforeEach(() => {
        mockViewMode = 'cards';
        mockSetViewMode.mockClear();
    });

    it('posiciona o switcher à esquerda do botão de relatórios', async () => {
        await renderFilterView();

        const header = screen.getByTestId('liquidacao-filter-header-actions');
        const switcher = screen.getByRole('tablist', { name: 'Modo de visualização' });
        const exportButton = screen.getByRole('button', { name: 'Baixar relatórios' });

        expect(header.firstElementChild).toBe(switcher.parentElement);
        expect(
            switcher.compareDocumentPosition(exportButton) & Node.DOCUMENT_POSITION_FOLLOWING,
        ).toBeTruthy();
        expect(screen.getByTestId('liquidacao-filter-header-actions')).toHaveAttribute(
            'data-disabled',
            'false',
        );
    });

    it('clique em Kanban persiste o modo via setter da URL', async () => {
        await renderFilterView();

        fireEvent.click(screen.getByRole('tab', { name: 'Kanban' }));

        expect(mockSetViewMode).toHaveBeenCalledWith('kanban');
    });

    it('clique em Cards persiste o modo via setter da URL', async () => {
        mockViewMode = 'kanban';

        await renderFilterView();

        fireEvent.click(screen.getByRole('tab', { name: 'Cards' }));

        expect(mockSetViewMode).toHaveBeenCalledWith('cards');
    });

    it('marca o tab ativo conforme viewMode da URL', async () => {
        mockViewMode = 'kanban';

        await renderFilterView();

        expect(screen.getByRole('tab', { name: 'Kanban' })).toHaveAttribute('aria-selected', 'true');
        expect(screen.getByRole('tab', { name: 'Cards' })).toHaveAttribute('aria-selected', 'false');
    });

    it('desabilita a grade operacional no modo CRM e mantém o switcher clicável', async () => {
        mockViewMode = 'crm';

        await renderFilterView();

        expect(screen.getByTestId('liquidacao-filter-header-actions')).toHaveAttribute(
            'data-disabled',
            'true',
        );
        expect(screen.getByRole('tab', { name: 'CRM' })).toHaveAttribute('aria-selected', 'true');

        fireEvent.click(screen.getByRole('tab', { name: 'Cards' }));

        expect(mockSetViewMode).toHaveBeenCalledWith('cards');
    });

    it('clique em CRM persiste o modo via setter da URL', async () => {
        await renderFilterView();

        fireEvent.click(screen.getByRole('tab', { name: 'CRM' }));

        expect(mockSetViewMode).toHaveBeenCalledWith('crm');
    });
});

describe('LiquidacaoFilterView — switcher falha', () => {
    beforeEach(() => {
        mockViewMode = 'cards';
        mockSetViewMode.mockClear();
    });

    it('não inverte a ordem do export quando o modo é kanban', async () => {
        mockViewMode = 'kanban';

        await renderFilterView();

        const switcher = screen.getByRole('tablist', { name: 'Modo de visualização' });
        const exportButton = screen.getByRole('button', { name: 'Baixar relatórios' });

        expect(
            switcher.compareDocumentPosition(exportButton) & Node.DOCUMENT_POSITION_FOLLOWING,
        ).toBeTruthy();
    });

    it('ainda chama o setter ao clicar no tab já ativo', async () => {
        await renderFilterView();

        fireEvent.click(screen.getByRole('tab', { name: 'Cards' }));

        expect(mockSetViewMode).toHaveBeenCalledWith('cards');
        expect(mockSetViewMode).not.toHaveBeenCalledWith('kanban');
    });
});

