'use client';

import dynamic from 'next/dynamic';
import { useOperationalListFilterQueryState } from '../../hooks/useOperationalListFilterQueryState';
import type { TLiquidacaoListViewMode } from '../../types/liquidacaoKanban';
import { DueDiligenceStatisticsView } from '../DueDiligenceScreen/Views/DueDiligenceStatisticsView';
import { OperationalFiltersCard } from '../shared/OperationalFiltersCard';
import { LiquidacaoCardsView } from './LiquidacaoCardsView';
import { LiquidacaoFilterView } from './LiquidacaoFilterView';
import { LiquidacaoSubstatusFilterSection } from './LiquidacaoSubstatusFilterSection';

const LiquidacaoSubstatusKanbanView = dynamic(
    () =>
        import('./LiquidacaoSubstatusKanbanView').then(
            (module) => module.LiquidacaoSubstatusKanbanView,
        ),
    { ssr: false },
);

const LiquidacaoCrmView = dynamic(
    () => import('./LiquidacaoCrmView').then((module) => module.LiquidacaoCrmView),
    { ssr: false },
);

function renderLiquidacaoListView(viewMode: TLiquidacaoListViewMode) {
    switch (viewMode) {
        case 'crm':
            return <LiquidacaoCrmView />;
        case 'kanban':
            return <LiquidacaoSubstatusKanbanView />;
        case 'cards':
            return <LiquidacaoCardsView />;
    }
}

export function LiquidacaoScreenView() {
    const { viewMode } = useOperationalListFilterQueryState();
    const isCrmView = viewMode === 'crm';

    return (
        <>
            <div className="col-span-full">
                <DueDiligenceStatisticsView />
            </div>

            <OperationalFiltersCard>
                <LiquidacaoFilterView />
            </OperationalFiltersCard>

            <div className="col-span-full">
                <LiquidacaoSubstatusFilterSection disabled={isCrmView} />
            </div>

            <div className="col-span-full">
                {renderLiquidacaoListView(viewMode)}
            </div>
        </>
    );
}

