'use client';

import { QueryKeys } from '@/constants/query-keys';
import { useQuery } from '@tanstack/react-query';
import { parseAsInteger, parseAsString, useQueryStates } from 'nuqs';
import { useMemo } from 'react';
import { KANBAN_COLUMN_BY_SUBSTATUS } from '../constants/liquidacaoKanbanPipeline';
import {
    LIQUIDACAO_FUNIL_SUBSTATUS_LABEL,
    LIQUIDACAO_FUNIL_SUBSTATUS_ORDER,
} from '../constants/liquidacaoSubstatusFunnel';
import { useOperationalListFilterQueryState } from '../hooks/useOperationalListFilterQueryState';
import type {
    ILiquidacaoSubstatusFilterChip,
    ILiquidacaoSubstatusFilterViewModel,
} from '../interfaces/liquidacaoSubstatusFilter';
import type { ILiquidacaoScreenService } from '../interfaces/services';
import type {
    TLiquidacaoFunilSubstatus,
    TLiquidacaoFunilSubstatusCounts,
} from '../types/liquidacaoKanban';
import {
    normalizeLiquidacaoFunilSubstatusFromUrl,
    resolveLiquidacaoFunilChipBarColor,
    resolveLiquidacaoFunilCountsFilters,
} from '../utils/liquidacaoSubstatusFunnel';

export interface IUseViewModelLiquidacaoSubstatusFilterDependencies {
    liquidacaoScreenService: ILiquidacaoScreenService;
}

function buildFunilChips(
    selectedSubstatus: TLiquidacaoFunilSubstatus | null,
    counts: Partial<TLiquidacaoFunilSubstatusCounts> | null | undefined,
): ILiquidacaoSubstatusFilterChip[] {
    return LIQUIDACAO_FUNIL_SUBSTATUS_ORDER.map((substatus) => ({
        sub_status: substatus,
        label: LIQUIDACAO_FUNIL_SUBSTATUS_LABEL[substatus],
        count: counts?.[substatus] ?? 0,
        barColor: resolveLiquidacaoFunilChipBarColor(KANBAN_COLUMN_BY_SUBSTATUS[substatus]),
        isSelected: selectedSubstatus === substatus,
    }));
}

export function useViewModelLiquidacaoSubstatusFilter({
    liquidacaoScreenService,
}: IUseViewModelLiquidacaoSubstatusFilterDependencies): ILiquidacaoSubstatusFilterViewModel {
    const [queryStates, setQueryStates] = useQueryStates({
        liqSubStatus: parseAsString,
        page: parseAsInteger.withDefault(1),
    });
    const { liquidacaoListApiFilters } = useOperationalListFilterQueryState();

    const selectedSubstatus = normalizeLiquidacaoFunilSubstatusFromUrl(queryStates.liqSubStatus);
    const countsFilters = useMemo(
        () => resolveLiquidacaoFunilCountsFilters(liquidacaoListApiFilters),
        [liquidacaoListApiFilters],
    );
    const countsQueryFingerprint = JSON.stringify(countsFilters);

    const { data: counts, isPending: isCountsLoading } = useQuery({
        queryKey: [QueryKeys.dueDiligence.liquidacaoSubstatusCounts, countsQueryFingerprint],
        queryFn: () => liquidacaoScreenService.getSubstatusCounts(countsFilters),
    });

    const chips = useMemo(
        () => buildFunilChips(selectedSubstatus, counts),
        [counts, selectedSubstatus],
    );

    function onSelectSubstatus(substatus: TLiquidacaoFunilSubstatus) {
        if (selectedSubstatus === substatus) {
            void setQueryStates({ liqSubStatus: null, page: 1 });
            return;
        }

        void setQueryStates({ liqSubStatus: substatus, page: 1 });
    }

    return {
        ui: {
            chips,
            selectedSubstatus,
            isCountsLoading,
        },
        handlers: {
            onSelectSubstatus,
        },
        constants: {
            chipsCatalog: LIQUIDACAO_FUNIL_SUBSTATUS_ORDER,
        },
    };
}

