12	import { useAvancarEmLiquidacaoMutation } from '../hooks/use-avancar-em-liquidacao-mutation';
13	import { useCessionarioDialogState } from '../hooks/use-cessionario-dialog-state';
14	import { useEnviarPosAquisicaoMutation } from '../hooks/use-enviar-pos-aquisicao-mutation';
15	import { useEscrituraPublicaDialogState } from '../hooks/use-escritura-publica-dialog-state';
16	import { useOperationalListFilterQueryState } from '../hooks/useOperationalListFilterQueryState';
17	import type { IDueCardsService, ILiquidacaoScreenService } from '../interfaces/services';
18	import { CessionarioService } from '../services/CessionarioService';
19	import type { TDueDiligenceDetailedCardItem } from '../types/dueItem';
20	import {
21	    createDueCardScreenHandlers,
22	    getIdwallStatus,
23	    getObsCount,
24	    getPendenciasData,
25	    resolveEffectiveStatusLiquidacao,
26	    scrollToTop,
27	} from '../utils';
28	
29	export interface UseViewModelCardsLiquidacaoParams {
30	    service: ILiquidacaoScreenService;
31	    dueCardsService: IDueCardsService;
32	    cessionarioService: CessionarioService;
33	}
34	
35	export function useViewModelCardsLiquidacao(params: UseViewModelCardsLiquidacaoParams) {
36	    const { service, dueCardsService, cessionarioService } = params;
37	    const rootRef = useRef<HTMLDivElement | null>(null);
38	    const openObservationSheet = useDueDiligenceStore((state) => state.openObservationSheet);
39	    const {
40	        page,
41	        setPage,
42	        liquidacaoListApiFilters: apiFilters,
43	        listQueryFingerprint,
44	    } = useOperationalListFilterQueryState();
45	    const router = useRouter();
46	    const [pageSize, setPageSize] = useState(10);
47	    const isFirstPageRender = useRef(true);
48	    const [avancarCessaoItemId, setAvancarCessaoItemId] = useState<string | null>(null);
49	    const { resolveEscrituraStatus } = useEscrituraPublicaDialogState();
50	    const enviarPosAquisicaoMutation = useEnviarPosAquisicaoMutation(dueCardsService);
51	    const avancarEmLiquidacaoMutation = useAvancarEmLiquidacaoMutation(dueCardsService);
52	
53	    const normalizeId = useCallback((id: string | number) => String(id), []);
54	
55	    const { data, isLoading, isFetching } = useQuery<
56	        PaginatedResponse<TDueDiligenceDetailedCardItem>
57	    >({
58	        queryKey: [QueryKeys.dueDiligence.list, 'liquidacao', page, listQueryFingerprint],
59	        queryFn: () => service.get(page, apiFilters),
60	    });
61	
62	    useEffect(() => {
63	        if (
64	            data?.results?.length &&
65	            (data.next || page === 1) &&
66	            data.results.length !== pageSize
67	        ) {
68	            setPageSize(data.results.length);
69	        }
70	    }, [data, page, pageSize]);
71	
72	    const totalPages = Math.max(1, Math.ceil((data?.count ?? 0) / Math.max(1, pageSize)));
73	    const hasNextPage = Boolean(data?.next);
74	    const hasPreviousPage = Boolean(data?.previous);
75	
76	    const prefetchNextPage = useCallback(
77	        async (fromPage = page) => {
78	            if (!hasNextPage) return;
79	            const nextPage = fromPage + 1;
80	            await queryClient.prefetchQuery({
81	                queryKey: ['due-diligence', 'liquidacao', 'items', nextPage, listQueryFingerprint],
82	                queryFn: () => service.get(nextPage, apiFilters),
83	            });
84	        },
85	        [apiFilters, hasNextPage, listQueryFingerprint, page, service],
86	    );
87	
88	    useEffect(() => {
89	        void prefetchNextPage();
90	    }, [prefetchNextPage]);
91	
92	    useEffect(() => {
93	        if (isFirstPageRender.current) {
94	            isFirstPageRender.current = false;
95	            return;
96	        }
97	
98	        scrollToTop(rootRef.current);
99	    }, [page]);
100	
101	    const goToNextPage = () => {
102	        if (!hasNextPage || isFetching) return;
103	        void setPage(page + 1);
104	    };
105	    const goToPreviousPage = () => {
106	        if (!hasPreviousPage || isFetching || page <= 1) return;
107	        void setPage(page - 1);
108	    };
109	
110	    const items = useMemo(() => data?.results ?? [], [data?.results]);
111	
112	    const cessionarioDialog = useCessionarioDialogState(items);
113	
114	    const resolveIdwallStatus = useCallback(
115	        (item: TDueDiligenceDetailedCardItem) => {
116	            const overrides = useDueDiligenceStore.getState().idwallStatusOverrides;
117	            const key = normalizeId(item.id);
118	            if (Object.prototype.hasOwnProperty.call(overrides, key)) {
119	                return overrides[key];
120	            }
121	            return getIdwallStatus(item);
122	        },
123	        [normalizeId],
124	    );
125	
126	    const avancarCessaoMutation = useMutation({
127	        onMutate: (item) => {
128	            setAvancarCessaoItemId(item.id);
129	        },
130	        mutationFn: (item: TDueDiligenceDetailedCardItem) => dueCardsService.avancarCessao(item.id),
131	        onSuccess: async () => {
132	            await queryClient.invalidateQueries({
133	                queryKey: ['due-diligence'],
134	                refetchType: 'all',
135	            });
136	            sendToastMessage({
137	                title: 'Sucesso',
138	                description: 'Avanço para cessão realizado com sucesso',
139	                type: 'success',
140	            });
141	        },
142	        onError: (error) => {
143	            console.error('Erro ao avançar para cessão:', error);
144	            sendToastMessage({
145	                title: 'Erro ao avançar para cessão',
146	                description: 'Tente novamente em instantes.',
147	                type: 'error',
148	            });
149	        },
150	        onSettled: () => {
151	            setAvancarCessaoItemId(null);
152	        },
153	    });
154	
155	    const handlers = useMemo(() => {
156	        return cessionarioDialog.patchHandlers({
157	            ...createDueCardScreenHandlers({
158	                router,
159	                items: data?.results ?? [],
160	                openObservationSheet,
161	            }),
162	            onRemoverCessionario: async (itemId: string, cessId: string) => {
163	                try {
164	                    await cessionarioService.deleteCessionario(itemId, cessId);
165	                    sendToastMessage({
166	                        title: 'Sucesso',
167	                        description: 'Cessionário desvinculado com sucesso',
168	                        type: 'success',
169	                    });
170	                    await queryClient.invalidateQueries({
171	                        queryKey: ['due-diligence'],
172	                        refetchType: 'all',
173	                    });
174	                } catch (error) {
175	                    console.error('Erro ao desvincular cessionário:', error);
176	                    sendToastMessage({
177	                        title: 'Erro ao desvincular cessionário',
178	                        description: 'Tente novamente em instantes.',
179	                        type: 'error',
180	                    });
181	                    throw error;
