import { PaginatedResponse } from '@/interfaces/IPaginatedResponse';
import { useDueDiligenceStore } from '@/store/useDueDiligenceStore';
import queryClient from '@/utils/queryClient';
import { useMutation, useQuery } from '@tanstack/react-query';
import { useRouter } from 'next/navigation';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { DueDiligenceStatusLiquidacao } from '../enums';
import { useAvancarEmLiquidacaoMutation } from '../hooks/use-avancar-em-liquidacao-mutation';
import { useCessionarioDialogState } from '../hooks/use-cessionario-dialog-state';
import { useEnviarPosAquisicaoMutation } from '../hooks/use-enviar-pos-aquisicao-mutation';
import { useEscrituraPublicaDialogState } from '../hooks/use-escritura-publica-dialog-state';
import { useOperationalListFilterQueryState } from '../hooks/useOperationalListFilterQueryState';
import type { IDueCardsService } from '../interfaces/services';
import { CessionarioService } from '../services/CessionarioService';
import type { TDueDiligenceDetailedCardItem } from '../types/dueItem';
import {
    createDueCardScreenHandlers,
    getIdwallStatus,
    getObsCount,
    getPendenciasData,
    resolveEffectiveStatusLiquidacao,
} from '../utils';
import { invalidateDueDiligenceList } from '../utils/invalidate-due-caches';

export function useViewModelCardsDue(service: IDueCardsService) {
    const enviarPosAquisicaoMutation = useEnviarPosAquisicaoMutation(service);
    const avancarEmLiquidacaoMutation = useAvancarEmLiquidacaoMutation(service);
    const normalizeId = useCallback((id: string | number) => String(id), []);
    const rootRef = useRef<HTMLDivElement | null>(null);
    const openObservationSheet = useDueDiligenceStore((state) => state.openObservationSheet);
    const cessionarioService = useMemo(() => new CessionarioService(), []);
    const {
        page,
        setPage,
        dueListApiFilters: apiFilters,
        listQueryFingerprint,
    } = useOperationalListFilterQueryState();
    const router = useRouter();
    const [pageSize, setPageSize] = useState(10);
    const isFirstPageRender = useRef(true);
    const [avancarCessaoItemId, setAvancarCessaoItemId] = useState<string | null>(null);
    const { resolveEscrituraStatus } = useEscrituraPublicaDialogState();
    const { data, isLoading, isFetching } = useQuery<
        PaginatedResponse<TDueDiligenceDetailedCardItem>
    >({
        queryKey: [QueryKeys.dueDiligence.list, 'due-diligence', page, listQueryFingerprint],
        queryFn: () => service.get(page, apiFilters),
    });

    useEffect(() => {
        if (
            data?.results?.length &&
            (data.next || page === 1) &&
            data.results.length !== pageSize
        ) {
            setPageSize(data.results.length);
        }
    }, [data, page, pageSize]);

    const totalPages = Math.max(1, Math.ceil((data?.count ?? 0) / Math.max(1, pageSize)));
    const hasNextPage = Boolean(data?.next);
    const hasPreviousPage = Boolean(data?.previous);

    const prefetchNextPage = useCallback(
        async (fromPage = page) => {
            if (!hasNextPage) return;
            const nextPage = fromPage + 1;
            await queryClient.prefetchQuery({
                queryKey: [QueryKeys.dueDiligence.list, nextPage, listQueryFingerprint],
                queryFn: () => service.get(nextPage, apiFilters),
            });
        },
        [apiFilters, hasNextPage, listQueryFingerprint, page, service],
    );

    useEffect(() => {
        if (isLoading || isFetching || !hasNextPage) return;

        const schedulePrefetch = () => {
            void prefetchNextPage();
        };

        if (typeof window.requestIdleCallback === 'function') {
            const idleId = window.requestIdleCallback(schedulePrefetch, { timeout: 3000 });
            return () => window.cancelIdleCallback(idleId);
        }

        const timeoutId = window.setTimeout(schedulePrefetch, 1500);
        return () => window.clearTimeout(timeoutId);
    }, [hasNextPage, isFetching, isLoading, prefetchNextPage]);

    useEffect(() => {
        if (isFirstPageRender.current) {
            isFirstPageRender.current = false;
            return;
        }

        const scrollableAncestor = (() => {
            let node = rootRef.current?.parentElement;

            while (node) {
                const style = window.getComputedStyle(node);
                const canScrollY =
                    (style.overflowY === 'auto' || style.overflowY === 'scroll') &&
                    node.scrollHeight > node.clientHeight;

                if (canScrollY) {
                    return node;
                }

                node = node.parentElement;
            }

            return null;
        })();

        if (scrollableAncestor) {
            scrollableAncestor.scrollTo({ top: 0, behavior: 'smooth' });
            return;
        }

        window.scrollTo({ top: 0, behavior: 'smooth' });
    }, [page]);

    const goToNextPage = () => {
        if (!hasNextPage || isFetching) return;
        void setPage(page + 1);
    };
    const goToPreviousPage = () => {
        if (!hasPreviousPage || isFetching || page <= 1) return;
        void setPage(page - 1);
    };

    const items = useMemo(() => data?.results ?? [], [data?.results]);

    const cessionarioDialog = useCessionarioDialogState(items);

    const resolveIdwallStatus = useCallback(
        (item: TDueDiligenceDetailedCardItem) => {
            const overrides = useDueDiligenceStore.getState().idwallStatusOverrides;
            const key = normalizeId(item.id);
            if (Object.prototype.hasOwnProperty.call(overrides, key)) {
                return overrides[key];
            }
            return getIdwallStatus(item);
        },
        [normalizeId],
    );

    const avancarCessaoMutation = useMutation({
        onMutate: (item) => {
            setAvancarCessaoItemId(item.id);
        },
        mutationFn: (item: TDueDiligenceDetailedCardItem) => service.avancarCessao(item.id),
        onSuccess: async () => {
            sendToastMessage({
                title: 'Sucesso',
                description: 'Avanço para cessão realizado com sucesso',
                type: 'success',
            });
            await queryClient.invalidateQueries({
                queryKey: ['due-diligence'],
                refetchType: 'all',
            });
        },
        onError: (error) => {
            console.error('Erro ao avançar para cessão:', error);
            sendToastMessage({
                title: 'Erro ao avançar para cessão',
                description: 'Tente novamente em instantes.',
                type: 'error',
            });
        },
        onSettled: () => {
            setAvancarCessaoItemId(null);
        },
    });

    const handlers = useMemo(() => {
        return cessionarioDialog.patchHandlers({
            ...createDueCardScreenHandlers({
                router,
                items: data?.results ?? [],
                openObservationSheet,
            }),
            onEnviarLiquidacao: async (item: TDueDiligenceDetailedCardItem) => {
                await service.enviarParaLiquidacao(item.id);
                invalidateDueDiligenceList(queryClient);
                await queryClient.invalidateQueries({
                    queryKey: ['due-diligence'],
                    refetchType: 'all',
                });
                sendToastMessage({
                    title: 'Sucesso',
                    description: 'Ativo enviado para liquidação com sucesso',
                    type: 'success',
                });
            },
            onDadosFinanceiros: async (item) => {
                if (enviarPosAquisicaoMutation.isLoadingForDueId(item.id)) return;
                await enviarPosAquisicaoMutation.mutateAsync(item.id);
            },
            onRemoverCessionario: async (itemId, cessId) => {
                try {
                    await cessionarioService.deleteCessionario(itemId, cessId);
                    sendToastMessage({
                        title: 'Sucesso',
                        description: 'Cessionário desvinculado com sucesso',
                        type: 'success',
                    });
                    await queryClient.invalidateQueries({
                        queryKey: ['due-diligence'],
                        refetchType: 'all',
                    });
                } catch (error) {
                    console.error('Erro ao desvincular cessionário:', error);
                    sendToastMessage({
                        title: 'Erro ao desvincular cessionário',
                        description: 'Tente novamente em instantes.',
                        type: 'error',
                    });
                    throw error;
                }
            },
            onAvancarCessao: async (item) => {
                const statusLiquidacao = resolveEffectiveStatusLiquidacao(item);
                if (statusLiquidacao !== DueDiligenceStatusLiquidacao.LIQ_EM_LIQUIDACAO) return;
                const isSameItemPending =
                    avancarCessaoMutation.isPending && avancarCessaoItemId === item.id;
                if (isSameItemPending) return;
                await avancarCessaoMutation.mutateAsync(item);
            },
            onAvancarEmLiquidacao: async (item) => {
                const statusLiquidacao = resolveEffectiveStatusLiquidacao(item);
                if (statusLiquidacao !== DueDiligenceStatusLiquidacao.LIQ_APROVADO_RESSALVA) return;
                if (avancarEmLiquidacaoMutation.isLoadingForDueId(item.id)) return;
                await avancarEmLiquidacaoMutation.mutateAsync(item.id);
            },
            onIdwall: (item) => {
                useDueDiligenceStore.getState().openIdwallDialog(item);
            },
            onEscrituraPublica: (item) => {
                useDueDiligenceStore.getState().openEscrituraDialog(item);
            },
        });
    }, [
        router,
        data,
        openObservationSheet,
        service,
        cessionarioDialog,
        cessionarioService,
        avancarCessaoMutation,
        avancarCessaoItemId,
        avancarEmLiquidacaoMutation,
        enviarPosAquisicaoMutation,
    ]);

    return {
        items,
        isLoading,
        isFetching,
        page,
        totalPages,
        totalItems: data?.count ?? 0,
        hasNextPage,
        hasPreviousPage,
        goToNextPage,
        goToPreviousPage,
        getPendenciasData,
        getObsCount,
        getCessionariosLista: cessionarioDialog.getLista,
        getTotalPctCessao: cessionarioDialog.getTotalPctCessaoForItem,
        getIdwallStatus: resolveIdwallStatus,
        getEscrituraStatus: resolveEscrituraStatus,
        handlers,
        rootRef,
        avancarCessaoItemId: avancarCessaoMutation.isPending ? avancarCessaoItemId : null,
        isAvancarEmLiquidacaoLoadingForDueId: avancarEmLiquidacaoMutation.isLoadingForDueId,
        isEnviarPosAquisicaoLoadingForDueId: enviarPosAquisicaoMutation.isLoadingForDueId,
    };
}

