/**
 * @jest-environment jsdom
 */
import { afterEach, beforeEach, describe, expect, it, jest } from '@jest/globals';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { act, renderHook, waitFor } from '@testing-library/react';
import type { ReactNode } from 'react';
import { QueryKeys } from '@/constants/query-keys';
import { DuePriorityLevel } from '@/enums/dueDiligence';
import type { ILiquidacaoCardKanban, TSubstatusKanbanBoardResponse } from '../../interfaces/liquidacaoKanban';
import type { ISubstatusKanbanService } from '../../interfaces/services';

type TCollaborationCallbacks = {
    onCardMoved?: () => void;
    onDueStateChanged?: () => void;
};

let collaborationCallbacks: TCollaborationCallbacks = {};

jest.mock('nuqs', () => ({
    parseAsInteger: { withDefault: () => ({}) },
    parseAsString: { withDefault: () => ({}) },
    parseAsStringEnum: () => ({ withDefault: () => ({}) }),
    useQueryStates: () => [
        {
            filter: 'TODOS',
            liqFilter: 'TODOS',
            modelo: 'v2',
            loa: null,
            credor: null,
            broker: null,
            priority_level: null,
            responsavel_scope: null,
            investidor_scope: null,
            investidor: null,
            esfera: null,
            ente_devedor: null,
            estado_ente_devedor: null,
            coordenador: null,
            host: null,
            liqSubStatus: null,
            page: 1,
            dataView: 'cards',
        },
        jest.fn(),
    ],
}));

jest.mock('@/store/userInfo', () => ({
    useUserInfoStore: (
        selector: (state: { data: { username: string; user: string; user_id: string } }) => unknown,
    ) => selector({ data: { username: 'analista', user: 'analista', user_id: 'user-1' } }),
}));

jest.mock('@/components/Collaboration/use-collaboration-user', () => ({
    useCollaborationCurrentUserId: () => 'user-1',
    useCollaborationUserProfile: () => ({
        userId: 'user-1',
        username: 'analista',
        displayName: 'Analista',
    }),
}));

jest.mock('@/components/Collaboration/collaboration-user', () => ({
    resolveCollaborationViewers: (viewers: unknown[]) => viewers,
}));

jest.mock('@/hooks/useLiquidacaoBoardCollaboration', () => ({
    useLiquidacaoBoardCollaboration: (callbacks: TCollaborationCallbacks) => {
        collaborationCallbacks = callbacks;
        return {
            isConnected: true,
        };
    },
}));

jest.mock('../../hooks/useOperationalListFilterQueryState', () => ({
    useOperationalListFilterQueryState: () => ({
        liquidacaoListApiFilters: [{ id: 'modelo', label: 'Modelo', value: 'v2' }],
        listQueryFingerprint: 'fingerprint-liquidacao-v2',
    }),
}));

jest.mock('../useViewModelSubstatusKanban', () =>
    jest.requireActual('../useViewModelSubstatusKanban'),
);

const mutateAsyncMock = jest.fn(async () => ({ priority_level: 'ALTA', is_priority: true }));

jest.mock('@/hooks/mutations/due-diligence', () => ({
    useSetDuePriorityMutation: () => ({
        mutateAsync: mutateAsyncMock,
    }),
}));

const sendToastMessageMock = jest.fn();

jest.mock('@/functions/messages/toastMessage', () => ({
    sendToastMessage: (...args: unknown[]) => sendToastMessageMock(...args),
}));

function makeCard(overrides: Partial<ILiquidacaoCardKanban> = {}): ILiquidacaoCardKanban {
    return {
        id: 'due-1',
        credor: 'Credor Teste',
        valor_liquido: 100000,
        status_liquidacao: null,
        sub_status: 'revisar_card_investimento',
        sub_status_display: 'Revisar Card de Investimento',
        responsaveis: {
            due_ativo: null,
            situacao_processual: null,
            certidoes: null,
        },
        tribunal: 'TRF1',
        prazo_fatal_liquidacao: '2026-10-01',
        fases_historico: [],
        sub_status_historico_fases: [],
        cessionarios_vinculados: [],
        priority_level: null,
        priority_level_display: null,
        pendencias_count: 0,
        ...overrides,
    };
}

function makeBoard(card = makeCard()): TSubstatusKanbanBoardResponse {
    return {
        total: 1,
        columns: [
            { id: 'revisao', name: 'Revisão', cards: [card] },
            { id: 'investidor', name: 'Investidor', cards: [] },
            { id: 'cartorio', name: 'Cartório', cards: [] },
            { id: 'fechamento', name: 'Fechamento', cards: [] },
        ],
    };
}

function createTestQueryClient() {
    return new QueryClient({
        defaultOptions: {
            queries: { retry: false },
            mutations: { retry: false },
        },
    });
}

function createWrapper(queryClient: QueryClient) {
    return function Wrapper({ children }: { children: ReactNode }) {
        return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>;
    };
}

function createService(board = makeBoard()): ISubstatusKanbanService {
    return {
        getBoard: jest.fn(async () => board),
        moveCard: jest.fn(async () => undefined),
    };
}

async function renderViewModel(
    service = createService(),
    queryClient = createTestQueryClient(),
) {
    const { useViewModelSubstatusKanban } = await import('../useViewModelSubstatusKanban');
    const rendered = renderHook(() => useViewModelSubstatusKanban({ service }), {
        wrapper: createWrapper(queryClient),
    });

    await waitFor(
        () => {
            expect(rendered.result.current.ui.total).toBe(1);
            expect(rendered.result.current.ui.boardColumns[0]?.cards).toHaveLength(1);
        },
        { timeout: 20_000 },
    );

    return { ...rendered, service, queryClient };
}

function getBoardQueryKey(queryClient: QueryClient) {
    return queryClient
        .getQueryCache()
        .getAll()
        .find((query) => query.queryKey[0] === QueryKeys.dueDiligence.substatusKanbanData)
        ?.queryKey;
}

describe('useViewModelSubstatusKanban', () => {
    jest.setTimeout(60_000);

    let queryClient: QueryClient;

    beforeEach(() => {
        collaborationCallbacks = {};
        queryClient = createTestQueryClient();
        mutateAsyncMock.mockReset();
        mutateAsyncMock.mockResolvedValue({ priority_level: 'ALTA', is_priority: true });
        sendToastMessageMock.mockReset();
    });

    afterEach(() => {
        queryClient.clear();
        queryClient.getQueryCache().clear();
    });

    it('consulta o board com a query key, fingerprint e username', async () => {
        const { service, queryClient, result } = await renderViewModel();

        expect(service.getBoard).toHaveBeenCalledWith([
            { id: 'modelo', label: 'Modelo', value: 'v2' },
        ]);
        expect(getBoardQueryKey(queryClient)).toEqual([
            QueryKeys.dueDiligence.substatusKanbanData,
            'fingerprint-liquidacao-v2',
            'analista',
        ]);
        expect(result.current.ui.columns.map((column) => column.id)).toEqual([
            'revisao',
            'investidor',
            'cartorio',
            'fechamento',
        ]);
        expect(result.current.ui.boardColumns[0]?.cards[0]?.id).toBe('due-1');
    });

    it('expõe label do header sem menção a arraste', async () => {
        const { result } = await renderViewModel();

        expect(result.current.constants.boardTotalLabel).toContain('clique no card');
        expect(result.current.constants.boardTotalLabel).not.toContain('arraste');
    });

    it('resolve entered_at do substatus atual e urgência pelo tempo no substatus', async () => {
        const enteredAt = '2026-08-01T10:00:00.000Z';
        const card = makeCard({
            sub_status: 'analise_investidor',
            sub_status_historico_fases: [
                {
                    sub_status: 'analise_investidor',
                    kanban_column: 'investidor',
                    entered_at: enteredAt,
                    left_at: null,
                    is_current: true,
                },
            ],
        });
        const { result } = await renderViewModel(createService(makeBoard(card)));

        expect(result.current.handlers.resolveCardSubstatusEnteredAt(card)).toBe(enteredAt);
        expect(result.current.handlers.isCardSubstatusTempoUrgente(card)).toBe(true);
    });

    it('dispara refetch quando o board remoto sinaliza mudança de card', async () => {
        const service = createService();
        const getBoard = service.getBoard as jest.MockedFunction<ISubstatusKanbanService['getBoard']>;
        getBoard.mockClear();

        await renderViewModel(service, queryClient);

        act(() => {
            collaborationCallbacks.onCardMoved?.();
        });

        await waitFor(() => {
            expect(getBoard.mock.calls.length).toBeGreaterThanOrEqual(2);
        });
    });

    it('dispara refetch quando o estado da due muda remotamente', async () => {
        const service = createService();
        const getBoard = service.getBoard as jest.MockedFunction<ISubstatusKanbanService['getBoard']>;
        getBoard.mockClear();

        await renderViewModel(service, queryClient);

        act(() => {
            collaborationCallbacks.onDueStateChanged?.();
        });

        await waitFor(() => {
            expect(getBoard.mock.calls.length).toBeGreaterThanOrEqual(2);
        });
    });

    it('aplica prioridade com update otimista e toast de sucesso', async () => {
        const { result, queryClient } = await renderViewModel();

        await act(async () => {
            await result.current.handlers.onPriorityChange('due-1', DuePriorityLevel.ALTA);
        });

        const board = queryClient.getQueryData<TSubstatusKanbanBoardResponse>(getBoardQueryKey(queryClient));
        expect(board?.columns[0]?.cards[0]?.priority_level).toBe(DuePriorityLevel.ALTA);
        expect(mutateAsyncMock).toHaveBeenCalledWith({
            dueId: 'due-1',
            priorityLevel: DuePriorityLevel.ALTA,
        });
        expect(sendToastMessageMock).toHaveBeenCalledWith(
            expect.objectContaining({ type: 'success', title: 'Prioridade Alta aplicada' }),
        );
        expect(result.current.ui.updatingPriorityId).toBeNull();
    });

    it('restaura o board e exibe toast de erro quando a mutation falha', async () => {
        mutateAsyncMock.mockRejectedValueOnce(new Error('network'));
        const { result, queryClient } = await renderViewModel();
        const previousBoard = queryClient.getQueryData<TSubstatusKanbanBoardResponse>(
            getBoardQueryKey(queryClient),
        );

        await act(async () => {
            await result.current.handlers.onPriorityChange('due-1', DuePriorityLevel.MEDIA);
        });

        const board = queryClient.getQueryData<TSubstatusKanbanBoardResponse>(getBoardQueryKey(queryClient));
        expect(board).toEqual(previousBoard);
        expect(sendToastMessageMock).toHaveBeenCalledWith(
            expect.objectContaining({ type: 'error', title: 'Erro ao alterar prioridade.' }),
        );
    });
});

